//! Generate files of the web components from Rust, e.g. the colors of the theme as CSS and
//! TypeScript and the grid shader in GLSL, so that they are defined only once in the workspace.
//!
//! The copyright notices of the generated files are the ones of `cargo xtask update-copyright`:
//! a generated file keeps its notice, a new one gets the notice of the current year.

use std::error::Error;
use std::path::{Path, PathBuf};

use mucad_viewer_utils::{
    EDGE_WEB_WGSL, GRID_WEB_WGSL, GRID_WGSL, LIGHTING_WGSL, Lighting, MODEL_WEB_WGSL,
    SILHOUETTE_WGSL, Theme,
};

use crate::change_version::workspace_root;
use crate::update_copyright::copyright_header;

/// The directory of the generated files, relative to the workspace root.
const GENERATED_DIR: &str = "editors/web-components/src/generated";

/// The source of the generated theme files.
const THEME_SOURCE: &str = "`Theme::default()` of `mucad-viewer-utils`";

/// The source of the generated grid shader.
const GRID_SOURCE: &str = "`GRID_WEB_WGSL` and `GRID_WGSL` of `mucad-viewer-utils`";

/// The source of the generated model shader.
const MODEL_SOURCE: &str =
    "`MODEL_WEB_WGSL`, `LIGHTING_WGSL` and `Lighting::default()` of `mucad-viewer-utils`";

/// The source of the generated edge shader.
const EDGE_SOURCE: &str = "`EDGE_WEB_WGSL` and `SILHOUETTE_WGSL` of `mucad-viewer-utils`";

/// The note of a generated file, which says where it comes from, e.g. [`THEME_SOURCE`].
fn note(source: &str) -> String {
    format!("Generated by `cargo xtask web` from {source}, do not edit.")
}

/// The license of the generated files, like the default of `cargo xtask update-copyright`.
const LICENSE_ID: &str = "AGPL-3.0-or-later";

/// A generated file: its path relative to the workspace root, its comment prefix and suffix
/// and its content without copyright notice.
struct Generated {
    path: PathBuf,
    comment: (&'static str, &'static str),
    content: String,
}

/// Write the generated files, or with `check` only report the ones which are outdated.
pub fn web(check: bool) -> Result<(), Box<dyn Error>> {
    let root = workspace_root();
    let mut outdated = Vec::new();
    for generated in generated_files()? {
        let path = generated.path;
        let file = root.join(&path);
        let current = std::fs::read_to_string(&file).unwrap_or_default();
        let (prefix, suffix) = generated.comment;
        let header = copyright_notice(&current).map_or_else(
            || {
                let year = chrono::Datelike::year(&chrono::Utc::now()).to_string();
                copyright_header(prefix, suffix, &year, LICENSE_ID)
            },
            str::to_string,
        );
        let content = header + &generated.content;
        if current == content {
            continue;
        }
        if check {
            outdated.push(path);
        } else {
            std::fs::create_dir_all(file.parent().unwrap_or(Path::new(".")))?;
            std::fs::write(&file, content)?;
            println!("Generated {}", path.display());
        }
    }
    if outdated.is_empty() {
        Ok(())
    } else {
        let files: Vec<_> = outdated
            .iter()
            .map(|path| path.display().to_string())
            .collect();
        Err(format!(
            "Outdated generated files, run `cargo xtask web`: {}",
            files.join(", ")
        )
        .into())
    }
}

/// The copyright notice at the start of `content` up to the empty line after it, if it has one.
fn copyright_notice(content: &str) -> Option<&str> {
    let first_line = content.lines().next()?;
    if !first_line.contains("Copyright ©") {
        return None;
    }
    content.find("\n\n").map(|end| &content[..end + 2])
}

/// The generated files.
fn generated_files() -> Result<Vec<Generated>, Box<dyn Error>> {
    let theme = Theme::default();
    let dir = Path::new(GENERATED_DIR);
    Ok(vec![
        Generated {
            path: dir.join("theme.css"),
            comment: ("/*", "*/"),
            content: theme_css(&theme)?,
        },
        Generated {
            path: dir.join("theme.ts"),
            comment: ("//", ""),
            content: theme_ts(&theme)?,
        },
        Generated {
            path: dir.join("grid.ts"),
            comment: ("//", ""),
            content: grid_ts()?,
        },
        Generated {
            path: dir.join("model.ts"),
            comment: ("//", ""),
            content: model_ts()?,
        },
        Generated {
            path: dir.join("edge.ts"),
            comment: ("//", ""),
            content: edge_ts()?,
        },
    ])
}

/// The colors of the theme as CSS custom properties, e.g. `--primary: #020D1A;`.
fn theme_css(theme: &Theme) -> Result<String, Box<dyn Error>> {
    Ok(format!(
        "/* {note} */\n\
         \n\
         /* The colors of the µcad theme. */\n\
         {css}",
        note = note(THEME_SOURCE),
        css = theme.to_css()?
    ))
}

/// The colors of the theme as TypeScript constant `theme`, e.g. `primary: "#020D1A"`.
fn theme_ts(theme: &Theme) -> Result<String, Box<dyn Error>> {
    let toml: toml_edit::DocumentMut = theme.to_toml()?.parse()?;
    let colors: String = toml
        .iter()
        .filter(|(name, _)| *name != "name")
        .filter_map(|(name, item)| Some(format!("  {name}: \"{}\",\n", item.as_str()?)))
        .collect();
    Ok(format!(
        "// {note}\n\
         \n\
         /** The colors of the µcad theme, also as CSS custom properties in `theme.css`. */\n\
         export const theme = {{\n\
         {colors}\
         }} as const;\n",
        note = note(THEME_SOURCE)
    ))
}

/// The grid shader in GLSL ES 3.00 for three.js.
fn grid_ts() -> Result<String, Box<dyn Error>> {
    let shader =
        crate::glsl::to_webgl(GRID_WEB_WGSL, "grid_web.wgsl", &[("grid.wgsl", GRID_WGSL)])?;
    shader_ts(
        "grid",
        "The grid shader of the µcad viewers",
        "the position at location 0",
        &shader,
        "",
        GRID_SOURCE,
    )
}

/// The shader of the lit models in GLSL ES 3.00 for three.js, with the default lighting.
fn model_ts() -> Result<String, Box<dyn Error>> {
    let shader = crate::glsl::to_webgl(
        MODEL_WEB_WGSL,
        "model_web.wgsl",
        &[("lighting.wgsl", LIGHTING_WGSL)],
    )?;
    // The floats of `Lighting::default()` in the order of the members of the WGSL struct.
    let lighting = Lighting::default();
    let values: [(&str, Vec<f32>); 8] = [
        ("key_direction", lighting.key_direction.to_array().to_vec()),
        ("key", vec![lighting.key]),
        (
            "fill_direction",
            lighting.fill_direction.to_array().to_vec(),
        ),
        ("fill", vec![lighting.fill]),
        ("sky", vec![lighting.sky]),
        ("ground", vec![lighting.ground]),
        ("specular", vec![lighting.specular]),
        ("shininess", vec![lighting.shininess]),
    ];
    let block = shader
        .uniform_blocks
        .get("lighting")
        .ok_or("No uniform block `lighting`")?;
    let names: Vec<&str> = block
        .members
        .iter()
        .map(|(name, _)| name.as_str())
        .collect();
    let expected: Vec<&str> = values.iter().map(|(name, _)| *name).collect();
    if names != expected {
        return Err(format!("The members of `Lighting` changed: {names:?}").into());
    }
    let floats: Vec<String> = values
        .iter()
        .flat_map(|(_, floats)| floats.iter().map(|float| format!("{float:?}")))
        .collect();
    shader_ts(
        "model",
        "The shader of the lit 3D models of the µcad viewers",
        "the position at location 0 and the normal at location 1",
        &shader,
        &format!(
            "\x20 /** The floats of `Lighting::default()` for the uniform block `lighting`. */\n\
             \x20 lighting: [{}],\n",
            floats.join(", ")
        ),
        MODEL_SOURCE,
    )
}

/// The shader of the edge lines in GLSL ES 3.00 for three.js.
fn edge_ts() -> Result<String, Box<dyn Error>> {
    let shader = crate::glsl::to_webgl(
        EDGE_WEB_WGSL,
        "edge_web.wgsl",
        &[("silhouette.wgsl", SILHOUETTE_WGSL)],
    )?;
    shader_ts(
        "edge",
        "The shader of the edge lines of the 3D models of the µcad viewers",
        "the position at location 0, the normals of the two triangles of the edge at locations 1 \
         and 2 and its midpoint at location 3",
        &shader,
        "",
        EDGE_SOURCE,
    )
}

/// A TypeScript module, which exports the constant `name` with the shaders without `#version`,
/// which three.js writes with `glslVersion: THREE.GLSL3`, with the names of the attributes and of
/// the uniform blocks, which naga generated, and with `extra` entries.
fn shader_ts(
    name: &str,
    description: &str,
    attributes_description: &str,
    shader: &crate::glsl::WebGlShader,
    extra: &str,
    source: &str,
) -> Result<String, Box<dyn Error>> {
    // three.js writes `#version 300 es` itself with `glslVersion: THREE.GLSL3`, before its defines.
    let without_version = |glsl: &str| -> Result<String, Box<dyn Error>> {
        let glsl = glsl
            .strip_prefix("#version 300 es\n")
            .ok_or("GLSL without `#version 300 es`")?;
        Ok(glsl.trim_start().to_string())
    };
    let vertex_shader = template_literal(&without_version(&shader.vertex)?);
    let fragment_shader = template_literal(&without_version(&shader.fragment)?);
    // The attributes by their locations from 0.
    let attributes: Vec<String> = shader
        .attributes
        .iter()
        .enumerate()
        .map(|(index, (location, attribute))| {
            if *location as usize == index {
                Ok(format!("\"{attribute}\""))
            } else {
                Err(format!("No vertex attribute at location {index}"))
            }
        })
        .collect::<Result<_, _>>()?;
    let blocks: String = shader
        .uniform_blocks
        .iter()
        .map(|(variable, block)| {
            let members: Vec<String> = block
                .members
                .iter()
                .map(|(name, floats)| format!("[\"{name}\", {floats}]"))
                .collect();
            format!(
                "    {variable}: {{ name: \"{}\", members: [{}] }},\n",
                block.name,
                members.join(", ")
            )
        })
        .collect();
    Ok(format!(
        "// {note}\n\
         \n\
         /**\n \
          * {description} in GLSL ES 3.00 for WebGL2, without `#version`, which three.js writes\n \
          * with `glslVersion: THREE.GLSL3`.\n \
          */\n\
         export const {name} = {{\n\
         \x20 vertexShader: {vertex_shader},\n\
         \x20 fragmentShader: {fragment_shader},\n\
         \x20 /** The vertex attributes by their locations: {attributes_description}. */\n\
         \x20 attributes: [{attributes}],\n\
         \x20 /**\n\
         \x20  * The uniform blocks by the names of their variables in WGSL, with the names and the numbers\n\
         \x20  * of floats of the members in the order of their std140 layout, e.g. for\n\
         \x20  * `THREE.UniformsGroup`.\n\
         \x20  */\n\
         \x20 uniformBlocks: {{\n\
         {blocks}\
         \x20 }},\n\
         {extra}\
         }} as const;\n",
        note = note(source),
        attributes = attributes.join(", "),
    ))
}

/// `text` as TypeScript template literal, e.g. for multiline GLSL.
fn template_literal(text: &str) -> String {
    let escaped = text
        .replace('\\', "\\\\")
        .replace('`', "\\`")
        .replace("${", "\\${");
    format!("`{escaped}`")
}
